<template>
  <view class="popup-container">
	<view  class="close-containner">
		<view class="close-btn" @tap="close()">
	</view>
	</view>
    <!-- 弹窗内容 -->
    <view class="popup-content">
      <!-- 标题 -->
      <view class="title"></view>

      <!-- 解锁按钮 -->
      <!-- <view class="unlock-pop"></view> -->

		<view
		  class="claim-btn"
		  @tap="showAd()"
		>
		  {{message ? message : '看广告解锁一集'}}
		</view>
      <!-- 领取按钮 -->
		<!-- <view
		  class="claim-btn"
		  :disabled="!canClick"
		  @tap="showAd()"
		>
		  看广告解锁三集
		  {{ canClick ? '立即领取' : countdown + '秒后立即领取' }}
		</view>
		<view class="highlight-msg">
			{{message?message:''}}
		</view> -->
    </view>
  </view>
</template>

<script>
var plugin = requirePlugin("playlet-plugin");
export default {
  props: {
	  ext: {
	    type: String,
			default: '',
	  },
  },
  data() {
		return {
			countdown: 3,      // 倒计时秒数
			intervalId: null,  // 定时器id
			videoAd: null, // 激励广告
			canClick: false,
			pm: null,
			message: ''
		};
  },
  mounted() {
	this.pm = plugin.PlayletManager.getPageManager(this.ext)
    this.getAd();
  },
  methods: {
    startCountdown() {
      this.intervalId = setInterval(() => {
        if (this.countdown > 1) {
          this.countdown--;
        } else {
					this.canClick = true
          clearInterval(this.intervalId);
          this.countdown = 0;
					this.showAd()
        }
      }, 1000);
    },
  
    getAd() {
      let videoAd = null;
  
      if (wx.createRewardedVideoAd) {
        videoAd = wx.createRewardedVideoAd({
          adUnitId: '__AD_UNIT_ID__'
        });
				// this.startCountdown()
        videoAd.onLoad(() => {});
        videoAd.onError((err) => {
          console.error('激励视频广告加载失败', err);
        });
      }
	  
	  this.videoAd = videoAd
    },
	
	showAd() {
		this.$trackEvent(`moon_show_ad_open_area`);
		let videoAd = this.videoAd
		this.message = '正在解锁!!'
		if (videoAd) {
		  videoAd.show().catch(() => {
		    videoAd.load()
		      .then(() => videoAd.show())
		      .catch(err => {
		        console.error('激励视频广告显示失败', err);
		      });
		  });
		  videoAd.onClose(res => {
				// 用户点击了【关闭广告】按钮
				this.pm.play()
				this.pm.updateOpenArea({
					showLeft: false
				})
				if (res && res.isEnded) {
					// 正常播放结束
					const info = this.pm.getInfo();
					this.pm.isCanPlay({
					    serialNo: info.serialNo+1,
					    serialList: [{
					      start_serial_no: info.serialNo+1,
					      end_serial_no: info.serialNo+1,
					      status: 1, // 解锁
					    }],
					})
				} else {
					// 播放中途退出
				}
		  })
		} else{
			this.message = '正在解锁, 请稍后!!'
		}
	},
	
	close(){
		this.$trackEvent(`moon_close_ad_open_area`);
		console.log('点击了close')
		this.pm.updateOpenArea({
		  showLeft: false, // 显示 open-area-left 组件
		})
	}
  }
};
</script>

