	margin: 0rpx 100rpx 80rpx 100rpx;
}

.title {
	height: 300rpx;
	width: 500rpx;
	background-image: url('data:image/jpeg;base64,');	
	background-size: 100% auto;
	background-position: center;
	background-repeat: no-repeat;
	margin: 300rpx 100rpx 0rpx 100rpx;
}

.claim-btn {
  width: 100% auto;
  margin: 0rpx 30rpx;
  /* 1. 形状与尺寸 */
  padding: 40rpx 90rpx; /* 调整内边距以获得合适的尺寸 */
  border-radius: 80rpx; /* 创建胶囊形状 */
  
  /* 2. 文字样式 */
  text-align: center;
  color: #f02a25; /* 一个比较鲜艳的红色 */
  font-weight: bold;
  font-size: 46rpx;
   /* 白色细阴影，让文字更清晰 */
  text-shadow: 0 1px 1px rgba(255, 255, 255, 0.5);
  
  /* 3. 边框 */
  border: 2rpx solid #c87600; /* 深黄色/浅棕色边框 */
  
  /* 4. 背景和光泽效果 (核心) */
  /* 使用两个线性渐变叠加：一个是白色高光层，另一个是黄色基础层 */
  background: 
    /* 高光层: 从顶部半透明白色渐变到中部几乎透明，然后完全透明 */
    linear-gradient(
      to bottom, 
      rgba(255, 255, 255, 0.7), 
      rgba(255, 255, 255, 0.1) 50%, 
      transparent 50%
    ),
    /* 基础颜色层: 从亮黄色到橙黄色的渐变 */
    linear-gradient(to bottom, #ffd700, #ff9900);
    
  /* 5. 按钮阴影，使其有立体感 */
  box-shadow: 0 4rpx 8rpx rgba(0, 0, 0, 0.2);
  
  /* 6. 其他默认样式重置 */
  outline: none; /* 移除点击时的轮廓 */
  
  /* 7. (可选) 交互效果 */
  transition: all 0.2s ease;
}

/* 按下时的效果 */
.claim-btn:active {
  transform: translateY(2rpx); /* 轻微下沉 */
  box-shadow: 0 2rpx 4rpx rgba(0, 0, 0, 0.2); /* 阴影变小 */
}

/* 禁用时的样式 (根据你的代码) */
